CREATE UNIQUE INDEX "workspaces_personalOwnerId_key" ON "workspaces"("personalOwnerId");

-- One Personal per account (SHO-285 Update 2): the Personal each user owns
-- becomes *the* Personal, and a cloud one (`hostInstanceId IS NULL`) beats a
-- desktop-hosted one because the cloud's is canonical (Russell, 2026-11-04) —
-- picking a hosted row here would pin every job to that one desktop. Duplicates
-- keep a null owner so the unique index accepts them and the merge can still
-- find them by `kind = 'personal'`.
UPDATE "workspaces"
   SET "personalOwnerId" = (
        SELECT m."userId"
          FROM "members" m
         WHERE m."workspaceId" = "workspaces"."id" AND m."role" = 'owner'
         LIMIT 1
       )
 WHERE "kind" = 'personal'
   AND "id" = (
        SELECT w2."id"
          FROM "workspaces" w2
          JOIN "members" m2 ON m2."workspaceId" = w2."id" AND m2."role" = 'owner'
         WHERE w2."kind" = 'personal'
           AND m2."userId" = (
                SELECT m3."userId" FROM "members" m3
                 WHERE m3."workspaceId" = "workspaces"."id" AND m3."role" = 'owner' LIMIT 1
               )
         ORDER BY (w2."hostInstanceId" IS NULL) DESC,
                  w2."createdAt" ASC,
                  w2."id" ASC
         LIMIT 1
       );

-- Background jobs run where they were requested (SHO-285 Update 2). A job that
-- already exists in a hosted workspace keeps running on that desktop (Part 1's
-- rule), so pin it there rather than letting the cloud pick it up.
UPDATE "agent_schedules"
   SET "runOnInstanceId" = (
        SELECT w."hostInstanceId" FROM "workspaces" w WHERE w."id" = "agent_schedules"."workspaceId"
       )
 WHERE "runOnInstanceId" IS NULL
   AND (SELECT w."hostInstanceId" FROM "workspaces" w WHERE w."id" = "agent_schedules"."workspaceId") IS NOT NULL;

UPDATE "agent_configs"
   SET "runOnInstanceId" = (
        SELECT w."hostInstanceId"
          FROM "projects" p JOIN "workspaces" w ON w."id" = p."workspaceId"
         WHERE p."id" = "agent_configs"."projectId"
       )
 WHERE "runOnInstanceId" IS NULL
   AND (
        SELECT w."hostInstanceId"
          FROM "projects" p JOIN "workspaces" w ON w."id" = p."workspaceId"
         WHERE p."id" = "agent_configs"."projectId"
       ) IS NOT NULL;

